import assets from "./proof-of-work-assets.json";
import { projectById } from "./projects";
import type { ServiceSlug } from "./services";

/**
 * Drawing excerpts shown as proof of work. The images are generated by
 * `npm run proof` from confidential PDFs kept outside this repository: cropped
 * clear of title blocks and logos, reduced and watermarked.
 *
 * `project` is the only place a drawing is tied to a project, and project pages
 * read it, so the two cannot drift apart. Set it from the sheet's title block,
 * never the filename. Use null for work on a project this site does not list;
 * such drawings are captioned as other experience, and their client, project and
 * drawing number must never appear here.
 */
export type DrawingSampleId = keyof typeof assets;

type ListedProjectId = "onshore-civil-structural" | "offshore-structural" | "brownfield-modifications";

type DrawingDetails = { title: string; discipline: string; project: ListedProjectId | null };

export type DrawingSample = Omit<DrawingDetails, "project"> & { id: DrawingSampleId; src: string; projectName?: string };

const details: Record<DrawingSampleId, DrawingDetails> = {
  "bridge-framing": { title: "Pipe bridge framing elevations", discipline: "Structural steel", project: "onshore-civil-structural" },
  "bridge-plan": { title: "Pipe bridge framing plans", discipline: "Structural steel", project: "onshore-civil-structural" },
  "bridge-foundation": { title: "Pipe bridge foundation reinforcement", discipline: "RCC", project: "onshore-civil-structural" },
  "jacket-frame-a": { title: "Jacket frame elevation", discipline: "Offshore steel", project: "offshore-structural" },
  "jacket-frame-b": { title: "Jacket bracing elevations", discipline: "Offshore steel", project: "offshore-structural" },
  "jacket-plan": { title: "Jacket framing plan and details", discipline: "Offshore steel", project: "offshore-structural" },
  "manifold-lifting": { title: "Manifold lifting arrangement and bill of material", discipline: "Structural steel", project: "brownfield-modifications" },
  "manifold-framing": { title: "Manifold framing plan", discipline: "Structural steel", project: "brownfield-modifications" },
  "manifold-elevations": { title: "Manifold elevations and stair access", discipline: "Structural steel", project: "brownfield-modifications" },
  "tank-platform-frames": { title: "Tank platform line frames", discipline: "Structural steel", project: null },
  "container-structure": { title: "Removable container structural GA", discipline: "Structural steel", project: null },
  "stair-tower": { title: "Stair tower part plans", discipline: "Structural steel", project: null },
  "deck-penetrations": { title: "Deck penetration plan", discipline: "Detail drawing", project: null },
  "evaporation-pond": { title: "Evaporation pond layout", discipline: "Civil", project: null },
  "tank-platform": { title: "Tank access platform framing", discipline: "Structural steel", project: null },
  "boundary-foundations": { title: "Precast column and drain details", discipline: "RCC", project: null },
  "foundation-details": { title: "Column and foundation details", discipline: "RCC", project: null },
  "transformer-lifting-model": { title: "Transformer lifting frame model and plans", discipline: "3D model", project: null },
  "generator-base-frame": { title: "Generator base frame model and details", discipline: "3D model", project: null },
  "seal-transformer-lifting": { title: "Transformer lifting GA, details and model", discipline: "3D model", project: null },
  "roof-opening-weld-map": { title: "Roof opening strengthening weld map", discipline: "Modification", project: null },
  "grating-shop-drawing": { title: "Grating shop drawing with material list", discipline: "Documentation", project: null },
};

const sampleIds = Object.keys(details) as DrawingSampleId[];

export const drawingSamples = (ids: readonly DrawingSampleId[]): DrawingSample[] =>
  ids.map((id) => {
    const { project, ...rest } = details[id];
    return { ...rest, id, src: assets[id], projectName: project ? projectById(project)?.name : undefined };
  });

/** Every drawing belonging to a project; an empty list means the project has none to show. */
export const drawingsForProject = (projectId: string) =>
  drawingSamples(sampleIds.filter((id) => details[id].project === projectId));

/**
 * Projects with no drawings of their own show the closest work by type instead.
 * These are not drawings from the project, and ProjectCaseStudy must say so
 * wherever they appear.
 */
const similarWorkIds: Partial<Record<string, DrawingSampleId[]>> = {
  "steel-detailing": ["tank-platform", "tank-platform-frames", "container-structure"],
  "rcc-detailing": ["boundary-foundations", "foundation-details", "bridge-foundation"],
  "plant-3d-modelling": ["transformer-lifting-model", "generator-base-frame", "stair-tower"],
  "drawings-qaqc": ["seal-transformer-lifting", "deck-penetrations", "grating-shop-drawing"],
};

export const similarWorkForProject = (projectId: string) => drawingSamples(similarWorkIds[projectId] ?? []);

/** Up to three per place: drawings from projects listed on the site first, then other experience. */
export const serviceDrawingIds: Record<ServiceSlug, DrawingSampleId[]> = {
  "civil-structural-drafting": ["bridge-plan", "manifold-framing", "evaporation-pond"],
  "plant-structural-3d-modelling": ["transformer-lifting-model", "generator-base-frame", "seal-transformer-lifting"],
  "steel-detailing-fabrication": ["bridge-framing", "jacket-frame-a", "tank-platform"],
  "rcc-reinforcement-detailing": ["bridge-foundation", "boundary-foundations", "foundation-details"],
  "brownfield-structural-modifications": ["manifold-elevations", "manifold-framing", "roof-opening-weld-map"],
  "material-takeoffs-documentation": ["manifold-lifting", "grating-shop-drawing"],
};

export const homeDrawingIds: DrawingSampleId[] = ["bridge-framing", "jacket-frame-b", "manifold-lifting"];
